import { Link, useHistory } from "react-router-dom";
import { decodeToken, logout } from "../utils/auth";

const Navbar = () => {
    const history = useHistory();
    const user = decodeToken(); 
    console.log("user role")

    const handleLogout = () => {
        logout();
        history.push("/user/login");
    };

    return (
        <nav className="navbar">
            <div className="navbar-content">
                <Link to="/" className="navbar-brand">AI Hiring</Link>

                <ul className="navbar-nav">

                    {/* Not logged in */}
                    {!user && (
                        <>
                            <li><Link to="/user/login">User Login</Link></li>
                            <li><Link to="/company/login">Company Login</Link></li>
                            <li><Link to="/privacy">Privacy</Link></li>
                        </>
                    )}

                    {/* Job Seeker */}
                    {user && user.role === "user" && (
                        <>
                            <li><Link to="/jobs">Browse Jobs</Link></li>
                            <li><Link to="/user/dashboard">My Applications</Link></li>
                            <li><Link to="/user/profile">Profile</Link></li>
                            <li>
                                <button onClick={handleLogout} className="navbar-link">
                                    Logout
                                </button>
                            </li>
                        </>
                    )}

                    {/* Company */}
                    {user && user.role === "company" && (
                        <>
                            <li><Link to="/company/dashboard">My Jobs</Link></li>
                            <li>
                                <button onClick={handleLogout} className="navbar-link">
                                    Logout
                                </button>
                            </li>
                        </>
                    )}

                </ul>
            </div>
        </nav>
    );
};

export default Navbar;
